CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, handle text NOT NULL UNIQUE, bio text NOT NULL DEFAULT '', avatar_asset_id uuid, role text NOT NULL DEFAULT 'user' CHECK(role IN('user','admin')), onboarded boolean NOT NULL DEFAULT false, settings jsonb NOT NULL DEFAULT '{}'::jsonb, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, user_agent text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),filename text NOT NULL,mime text NOT NULL,width int NOT NULL,height int NOT NULL,bytes int NOT NULL CHECK(bytes>0),sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD CONSTRAINT user_avatar_fk FOREIGN KEY(avatar_asset_id) REFERENCES assets(id);
CREATE TABLE model_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL,instructions text NOT NULL,enabled boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_profile_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),model_id uuid NOT NULL REFERENCES model_profiles(id),version int NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(model_id,version));
CREATE TABLE runtime_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,provider text NOT NULL CHECK(provider IN('mock','openai','local')),model text NOT NULL,enabled boolean NOT NULL DEFAULT false,endpoint_id text NOT NULL CHECK(endpoint_id IN('mock','openai','local')),max_input_tokens int NOT NULL,max_output_tokens int NOT NULL,timeout_ms int NOT NULL,concurrency int NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE heroes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE npcs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE adventures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),slug text NOT NULL UNIQUE,title text NOT NULL,synopsis text NOT NULL DEFAULT '',genre text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','private','unlisted','pending_review','published','archived')),version int NOT NULL DEFAULT 0,data jsonb NOT NULL,published_snapshot jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX adventure_catalog_idx ON adventures(status,updated_at);
CREATE TABLE adventure_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),adventure_id uuid NOT NULL REFERENCES adventures(id),version int NOT NULL CHECK(version>0),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(adventure_id,version));
CREATE TABLE favorites(user_id uuid NOT NULL REFERENCES users(id),adventure_id uuid NOT NULL REFERENCES adventures(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,adventure_id));
CREATE TABLE wallets(user_id uuid PRIMARY KEY REFERENCES users(id),balance int NOT NULL DEFAULT 0 CHECK(balance>=0));
CREATE TABLE ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),amount int NOT NULL CHECK(amount<>0),reason text NOT NULL,source_key text NOT NULL UNIQUE,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_user_idx ON ledger(user_id,created_at);
CREATE TABLE audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),action text NOT NULL,target_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),adventure_id uuid NOT NULL REFERENCES adventures(id),reason text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved','dismissed')),resolution text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,message text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE data_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN('export','deletion')),status text NOT NULL DEFAULT 'requested',created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION prevent_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only table'; END; $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION prevent_immutable_change();
CREATE TRIGGER adventure_version_immutable BEFORE UPDATE OR DELETE ON adventure_versions FOR EACH ROW EXECUTE FUNCTION prevent_immutable_change();
CREATE TRIGGER model_version_immutable BEFORE UPDATE OR DELETE ON model_profile_versions FOR EACH ROW EXECUTE FUNCTION prevent_immutable_change();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION prevent_immutable_change();
